evidence.quote:
"verdict": {
  "enum": [
    "approve",
    "changes_requested"
  ]

"required": [
  "status",
  "evidence"
],
"properties": {
  "status": {
    "enum": [
      "pass",
      "fail"
    ]
  },
  "evidence": {
    "type": "string"
  }

on:
  push:
    tags: ["v*"]
  workflow_dispatch:
    inputs:
      release: { type: boolean, default: false, description: "Run the release checks too" }
      test_filter: { type: string, default: "", description: "Passed to cargo test" }

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

include:
  - { id: linux-x64-gnu, os: ubuntu-24.04, build: zig, runtimes: node bun deno }
  - { id: linux-arm64-gnu, os: ubuntu-24.04-arm, build: zig, runtimes: node bun deno }
  - { id: linux-x64-musl, os: ubuntu-24.04, build: alpine, runtimes: node bun }
  - { id: linux-arm64-musl, os: ubuntu-24.04-arm, build: alpine, runtimes: node bun }
  - { id: darwin-arm64, os: macos-14, build: native, runtimes: node bun deno }
  - { id: darwin-x64, os: macos-15-intel, build: native, runtimes: node bun deno }
  - { id: win32-x64-msvc, os: windows-2022, build: native, runtimes: node bun deno }
  - { id: win32-arm64-msvc, os: windows-11-arm, build: native, runtimes: node bun deno }

```ts quickstart
import { run, spawn } from "hugr-omni";

const r = await run("git", ["status", "--short"], { timeoutMs: 10_000 });
console.log(r.success, r.stdout);

await using server = spawn("npm", ["run", "dev"]);
for await (const line of server.lines()) if (line.text.includes("ready")) break;
console.log(await server.processes()); // every process the server started, with parent links
// leaving the scope stops the server and everything it started
```

CommonJS works too: `const { run, spawn } = require("hugr-omni")`. `await using` needs Node 24+, Bun, Deno, or TypeScript
5.2+ compiling for Node 22; elsewhere write `try { ... } finally { await server.stop(); }`.

